import java.util.*;import java.util.concurrent.*;import com.tterrag.registrate.*;import com.tterrag.registrate.util.entry.*;import net.minecraft.resources.*;import net.minecraft.core.*;
public class RegistrateConcurrencyProbe {
 static final ResourceKey<Registry<Object>> KEY=ResourceKey.createRegistryKey(ResourceLocation.parse("fixture:unregistered"));
 static final class Owner extends AbstractRegistrate<Owner>{Owner(){super("fixture");} void capture(String name){accept(name,KEY,null,()->new Object(),holder->new RegistryEntry<>(this,holder));} boolean present(String n){return getOptional(n,KEY).isPresent();}}
 static int run(boolean locked,int threads,int each)throws Exception {Owner o=new Owner();var pool=Executors.newFixedThreadPool(threads);var barrier=new CyclicBarrier(threads);var fs=new ArrayList<Future<?>>();try{for(int t=0;t<threads;t++){final int id=t;fs.add(pool.submit(()->{try{barrier.await();for(int i=0;i<each;i++){String n="entry_"+id+"_"+i;if(locked){synchronized(o){o.capture(n);}}else{o.capture(n);}}}catch(Exception e){throw new RuntimeException(e);}}));}for(var f:fs)f.get(10,TimeUnit.SECONDS);}finally{pool.shutdownNow();pool.awaitTermination(3,TimeUnit.SECONDS);}var iterated=new HashSet<String>();for(var entry:o.getAll(KEY))iterated.add(entry.getId().getPath());int missing=0,orphan=0;for(int t=0;t<threads;t++)for(int i=0;i<each;i++){String name="entry_"+t+"_"+i;if(!o.present(name))missing++;else if(!iterated.contains(name))orphan++;}System.out.println("DETAIL locked="+locked+" expected="+(threads*each)+" iterated="+iterated.size()+" lookupMissing="+missing+" lookupPresentButNotIterated="+orphan);return missing;}
 public static void main(String[]a)throws Exception {net.minecraft.SharedConstants.tryDetectVersion();net.minecraft.server.Bootstrap.bootStrap();int sequential=run(false,1,2048);if(sequential!=0)throw new AssertionError("Sequential corrupt");int rawMissing=0,rawExceptions=0;for(int round=0;round<10;round++){try{int n=run(false,8,256);rawMissing+=n;System.out.println("RAW round="+round+" missing="+n);}catch(Exception e){rawExceptions++;System.out.println("RAW round="+round+" exception="+e);}}int lockedMissing=0;for(int round=0;round<10;round++)lockedMissing+=run(true,8,256);System.out.println("RESULT sequentialMissing="+sequential+" rawMissing="+rawMissing+" rawExceptions="+rawExceptions+" synchronizedMissing="+lockedMissing);if(lockedMissing!=0)throw new AssertionError("Synchronized loss");if(rawMissing!=0||rawExceptions!=0)throw new AssertionError("Production synchronized writer lost entries"); Owner e=new Owner();boolean threw=false;try{e.capture(null);}catch(RuntimeException expected){threw=true;}if(!threw)throw new AssertionError("Expected exception path absent");var executor=Executors.newSingleThreadExecutor();try{executor.submit(()->e.capture("after_exception")).get(2,TimeUnit.SECONDS);}finally{executor.shutdownNow();}if(!e.present("after_exception"))throw new AssertionError("Monitor not released");System.out.println("PASS production JVM monitor released after exceptional accept; another thread completed");}}
